{"explanation":"Maintains LRU residency, durable acknowledged values, lifetime versions, and per-entry flush eligibility. Writes always advance the key version; blocked insertions retain that counter. Acknowledgment persists only a dirty resident whose version matches a previously flushed version, preventing stale acknowledgments from persisting newer data.","program":"function solve(x){
 var c=x.config,e=x.event||{},s=x.state||{o:[],m:{},v:{},d:{}};
 var o=s.o,m=s.m,v=s.v,d=s.d,k=e.key,status='ignored',value=null,flush=[];
 function own(a,z){return Object.prototype.hasOwnProperty.call(a,z)}
 function touch(z){var i=o.indexOf(z);if(i>=0)o.splice(i,1);o.push(z)}
 function drop(z){var i=o.indexOf(z);if(i>=0)o.splice(i,1);delete m[z]}
 function clean(){for(var i=0;i<o.length;i++)if(!m[o[i]].dirty)return o[i];return null}
 function add(z,val,dirty){m[z]={value:val,version:v[z]||0,dirty:dirty,flushed:false};o.push(z)}
 if(e.type==='write'){
  v[k]=(v[k]||0)+1;
  if(own(m,k)){m[k].value=e.value;m[k].version=v[k];m[k].dirty=true;m[k].flushed=false;touch(k);status='written'}
  else if(o.length<c.slots){add(k,e.value,true);status='written'}
  else {var q=clean();if(q!==null){drop(q);add(k,e.value,true);status='written'}else status='blocked'}
 }else if(e.type==='read'){
  if(own(m,k)){value=m[k].value;touch(k);status='hit'}
  else if(own(d,k)){
   value=d[k];var q=o.length>=c.slots?clean():null;
   if(o.length<c.slots||(q!==null)){if(q!==null)drop(q);add(k,value,false)}
   status='durable'
  }else status='miss';
 }else if(e.type==='flush'){
  if(own(m,k)&&m[k].dirty){var a=m[k];a.flushed=true;flush.push({key:k,value:a.value,version:a.version});status='flushed'}
 }else if(e.type==='ack'){
  if(own(m,k)){var a=m[k];if(a.dirty&&a.version===e.version&&a.flushed){d[k]=a.value;a.dirty=false;a.flushed=false;status='persisted'}}
 }else if(e.type==='evict'){
  if(!own(m,k))status='missing';
  else if(m[k].dirty)status='blocked';
  else {drop(k);status='evicted'}
 }
 var dirty=o.filter(function(z){return m[z].dirty}).sort(),durable={};
 Object.keys(d).sort().forEach(function(z){durable[z]=d[z]});
 return {state:s,output:{status:status,value:value,flush:flush,cached:o.slice(),dirty:dirty,durable:durable}};
}"}
